## 产品资料（中文）
{
 "id": "TMB-50V",
 "factory_id": "NH-CUP",
 "name_zh": "500ml 双层真空保温杯",
 "name_en": "500ml Double-Wall Vacuum Insulated Tumbler",
 "specs": {
  "capacity_ml": 500,
  "inner_material": "304 stainless steel",
  "outer_material": "304 stainless steel, powder coated",
  "lid_material": "PP plastic",
  "insulation": "double-wall vacuum",
  "cold_retention": "about 24 h with ice (factory internal test, no third-party report)",
  "hot_retention": "about 12 h (factory internal test, no third-party report)",
  "care": "hand wash only, not dishwasher safe (powder-coated outer wall)",
  "features": [
   "slide lid, leak-resistant when closed",
   "no condensation on the outer wall",
   "fits most car cup holders"
  ]
 },
 "certifications_held": [
  "LFGB test report (304 body and PP lid)"
 ],
 "certifications_not_held": [
  "FDA food-contact test report"
 ],
 "material_tests": {
  "BPA": "盖子为 PP 材质，只有原料供应商的 BPA-free 声明，没有成品第三方报告"
 },
 "moq_units": 1000,
 "fob_ningbo_usd": {
  "1000-2999": 4.1,
  "3000+": 3.8
 },
 "packaging": "white box, 24 units per carton",
 "selling_points_zh": [
  "304 不锈钢内外胆",
  "双层真空：加冰约 24 小时（工厂内部测试，非第三方报告）",
  "外壁不冒汗",
  "滑盖，合上防漏",
  "只能手洗，不能进洗碗机（外壁喷粉）"
 ]
}

## 平台规则（知识库）
[
 {
  "id": "AMZ-01",
  "rule_zh": "亚马逊美国站现行规则：商品标题（Item name）含空格最多 75 个字符，适用于除媒体类以外的所有品类；放不下的卖点可写进 125 字符的 Item highlights。注意：网上很多文章还写着旧的 200 字符上限，2026-10-26 抓取的官方页面已是 75。"
 },
 {
  "id": "AMZ-02",
  "rule_zh": "标题不得出现 ! $ ? _ { } ^ ¬ ¦ 这些字符（品牌名本身含有的除外，应填到 Brand 字段）；~ # < > * 只能用于型号或尺寸等特定场景，不能做装饰。"
 },
 {
  "id": "AMZ-03",
  "rule_zh": "标题里不能写促销话术，官方举例是“free shipping”和“100% quality guaranteed”。"
 },
 {
  "id": "AMZ-04",
  "rule_zh": "官方最佳实践把“Hot Item”“Best seller”列为主观评价，标题里不应使用；不合规示例里也出现了全大写和 ★ 装饰。"
 },
 {
  "id": "AMZ-05",
  "rule_zh": "亚马逊五点描述（bullet points）的禁止内容里明确列出 eco-friendly、environmentally friendly、ecologically friendly、anti-microbial、anti-bacterial 等宣称，含这些词的五点可能被删改。"
 },
 {
  "id": "AMZ-06",
  "rule_zh": "商品详情页的标题、描述、五点和图片里都不允许出现电话号码、地址、邮箱或网址。"
 },
 {
  "id": "AMZ-07",
  "rule_zh": "标题、描述、五点和图片里不能写库存/供货情况、价格或成色信息。"
 },
 {
  "id": "US-01",
  "rule_zh": "FTC《绿色指南》16 CFR 260.4(b)：营销者不应做无限定的笼统环保宣称。条文例 1 明确说“Eco-friendly”这类说法会被理解为具有广泛环保益处，难以证实，因此具有欺骗性；只有附上清晰、可证实的具体限定（比如具体用了多少再生材料）才可能合规。"
 },
 {
  "id": "US-02",
  "rule_zh": "FTC《Made in USA 标签规则》16 CFR 323.2：除非最终组装或加工在美国完成、所有重要加工在美国、且全部或几乎全部部件在美国生产和采购，否则不得标“美国制造”；323.1 定义里 made、manufactured、built、produced、created、crafted in USA/America 都算。在中国生产的水壶不能这样写。"
 },
 {
  "id": "US-03",
  "rule_zh": "加州法规 27 CCR 25602(b)：如果产品需要 65 号提案警示，网购时警示须放在商品展示页，或在商品展示页放一个写着“WARNING”/“CA WARNING”/“CALIFORNIA WARNING”的明显链接，或在完成购买前醒目展示；买家要在网站里翻找才能看到的不算醒目。是否需要警示取决于产品是否会让消费者接触清单上的化学物质，需由供应商的检测资料确认，模型不能自行判断。"
 },
 {
  "id": "US-04",
  "rule_zh": "27 CCR 25603(a)：安全港警示须包含黄色等边三角形内黑色感叹号的标志、全大写加粗的“WARNING:”（或 CA WARNING: / CALIFORNIA WARNING:），写出至少一种化学物质的名称和危害类型（致癌 / 生殖危害），并附 www.P65Warnings.ca.gov。"
 }
]
